fonts_radius_outline.css:
:root {
    --sf-primary: #0f766e;
    --sf-primary-hover: #398e88;
    --sf-font-body: 'Inter Variable', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    --sf-font-heading: 'Lora Variable', Georgia, 'Times New Roman', serif;
    --sf-r-sm: 9px;
    --sf-r-md: 12px;
    --sf-r-lg: 18px;
    --sf-btn-bg: transparent;
    --sf-btn-text: var(--sf-primary, #171717);
    --sf-btn-bw: 2px;
}
@font-face {
    font-family: 'Inter Variable';
    font-style: normal;
    font-display: swap;
    font-weight: 100 900;
    src: url(/fonts/storefront/inter/inter-latin-wght-normal.woff2) format('woff2-variations');
    unicode-range: U+0100-02BA,U+02BD-02C5,U+02C7-02CC,U+02CE-02D7,U+02DD-02FF,U+0304,U+0308,U+0329,U+1D00-1DBF,U+1E00-1E9F,U+1EF2-1EFF,U+2020,U+20A0-20AB,U+20AD-20C0,U+2113,U+2C60-2C7F,U+A720-A7FF;
}
@font-face {
    font-family: 'Inter Variable';
    font-style: normal;
    font-display: swap;
    font-weight: 100 900;
    src: url(/fonts/storefront/inter/inter-cyrillic-wght-normal.woff2) format('woff2-variations');
    unicode-range: U+0460-052F,U+1C80-1C8A,U+20B4,U+2DE0-2DFF,U+A640-A69F,U+FE2E-FE2F;
}
